import hashlib
import json
import math


def verify(content, expected_sha256, expected_bytes):
    try:
        data = content.encode("utf-8")
    except UnicodeError as exc:
        raise ValueError("Content is not valid UTF-8") from exc

    if len(data) != expected_bytes or hashlib.sha256(data).hexdigest() != expected_sha256:
        raise ValueError("Content length or SHA-256 mismatch")

    def unique_object(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError("Duplicate JSON object key")
            result[key] = value
        return result

    def finite_float(token):
        value = float(token)
        if not math.isfinite(value):
            raise ValueError("Nonfinite JSON number")
        return value

    def parse_integer(token):
        negative = token.startswith("-")
        digits = token[1:] if negative else token
        value = 0
        for start in range(0, len(digits), 1000):
            chunk = digits[start:start + 1000]
            value = value * (10 ** len(chunk)) + int(chunk)
        return -value if negative else value

    def reject_constant(token):
        raise ValueError("Nonfinite JSON number")

    try:
        result = json.loads(
            content,
            object_pairs_hook=unique_object,
            parse_float=finite_float,
            parse_int=parse_integer,
            parse_constant=reject_constant,
        )
    except (RecursionError, OverflowError) as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(result, dict):
        raise ValueError("JSON root must be an object")
    return result
